// PayPal adapter.
// Orders + Payments use @paypal/paypal-server-sdk (the official PayPal Server SDK, generated by APIMatic).
// Payouts and webhook-signature verification are not in that SDK, so they use the documented REST endpoints.
// Without PAYPAL_CLIENT_ID/SECRET every call returns a SIMULATED result — no money moves.
import { Client, Environment, CheckoutPaymentIntent, OrdersController, PaymentsController } from '@paypal/paypal-server-sdk';
import crypto from 'node:crypto';

export const paypalConfigured = () => !!(process.env.PAYPAL_CLIENT_ID && process.env.PAYPAL_CLIENT_SECRET);
export const paypalMode = (): 'PAYPAL_SANDBOX' | 'PAYPAL_LIVE' | 'SIMULATED' =>
  !paypalConfigured() ? 'SIMULATED' : (process.env.PAYPAL_MODE || 'sandbox').toLowerCase() === 'live' ? 'PAYPAL_LIVE' : 'PAYPAL_SANDBOX';
const base = () => (paypalMode() === 'PAYPAL_LIVE' ? 'https://api-m.paypal.com' : 'https://api-m.sandbox.paypal.com');

let client: Client | null = null;
function sdk() {
  if (!client) client = new Client({
    clientCredentialsAuthCredentials: { oAuthClientId: process.env.PAYPAL_CLIENT_ID!, oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET! },
    environment: paypalMode() === 'PAYPAL_LIVE' ? Environment.Production : Environment.Sandbox,
    timeout: 30000,
  });
  return { orders: new OrdersController(client), payments: new PaymentsController(client) };
}

const sim = (p: string) => `SIM-${p}-${crypto.randomBytes(5).toString('hex').toUpperCase()}`;
const money = (v: number, currency = 'USD') => ({ currencyCode: currency, value: v.toFixed(2) });

function errMsg(e: any) {
  const body = e?.result || e?.body;
  return body ? `${e.message || 'PayPal error'}: ${typeof body === 'string' ? body.slice(0, 300) : JSON.stringify(body).slice(0, 300)}` : e?.message || String(e);
}

export async function createOrder(opts: { amount: number; currency?: string; intent: 'AUTHORIZE' | 'CAPTURE'; description: string; customId: string; returnUrl?: string; cancelUrl?: string }) {
  if (!paypalConfigured()) return { mode: 'SIMULATED' as const, orderId: sim('ORDER'), status: 'CREATED', approveUrl: null as string | null };
  const { orders } = sdk();
  const res = await orders.createOrder({
    body: {
      intent: opts.intent === 'AUTHORIZE' ? CheckoutPaymentIntent.Authorize : CheckoutPaymentIntent.Capture,
      purchaseUnits: [{ amount: money(opts.amount, opts.currency), description: opts.description.slice(0, 127), customId: opts.customId.slice(0, 127) }],
      ...(opts.returnUrl ? { applicationContext: { returnUrl: opts.returnUrl, cancelUrl: opts.cancelUrl } as any } : {}),
    },
    prefer: 'return=representation',
  });
  const o = res.result;
  return { mode: paypalMode(), orderId: o.id!, status: String(o.status), approveUrl: o.links?.find((l) => l.rel === 'approve' || l.rel === 'payer-action')?.href || null };
}

/** After buyer approval: authorize or capture the order, then re-read it from PayPal to verify. */
export async function completeOrder(orderId: string, intent: 'AUTHORIZE' | 'CAPTURE', expectedAmount: number) {
  if (!paypalConfigured()) {
    const nowMs = Date.now();
    return intent === 'AUTHORIZE'
      ? { mode: 'SIMULATED' as const, verified: true, status: 'AUTHORIZED', amount: expectedAmount, authorizationId: sim('AUTH'), expirationTime: new Date(nowMs + 29 * 864e5).toISOString(), honorPeriodEnds: new Date(nowMs + 3 * 864e5).toISOString(), captureId: undefined as string | undefined, raw: null }
      : { mode: 'SIMULATED' as const, verified: true, status: 'COMPLETED', amount: expectedAmount, captureId: sim('CAPTURE'), authorizationId: undefined as string | undefined, expirationTime: undefined as string | undefined, honorPeriodEnds: undefined as string | undefined, raw: null };
  }
  const { orders } = sdk();
  try {
    if (intent === 'AUTHORIZE') await orders.authorizeOrder({ id: orderId, prefer: 'return=representation' });
    else await orders.captureOrder({ id: orderId, prefer: 'return=representation' });
  } catch (e: any) {
    // Already processed (e.g. via a retried request) is fine — we verify below.
    if (!/ORDER_ALREADY_(AUTHORIZED|CAPTURED)/.test(JSON.stringify(e?.result || ''))) throw new Error(errMsg(e));
  }
  const verified = (await orders.getOrder({ id: orderId })).result;
  const pu: any = verified.purchaseUnits?.[0];
  const auth = pu?.payments?.authorizations?.[0];
  const cap = pu?.payments?.captures?.[0];
  const amt = Number((auth || cap)?.amount?.value || 0);
  const ok = intent === 'AUTHORIZE' ? auth?.status === 'CREATED' || auth?.status === 'PENDING' : cap?.status === 'COMPLETED' || cap?.status === 'PENDING';
  return {
    mode: paypalMode(), verified: ok && Math.abs(amt - expectedAmount) < 0.01, status: intent === 'AUTHORIZE' ? (ok ? 'AUTHORIZED' : String(auth?.status)) : String(cap?.status),
    amount: amt, authorizationId: auth?.id, captureId: cap?.id, expirationTime: auth?.expirationTime,
    honorPeriodEnds: auth ? new Date(Date.parse(auth.createTime || new Date().toISOString()) + 3 * 864e5).toISOString() : undefined, raw: { orderStatus: verified.status },
  };
}

export async function captureAuthorization(authorizationId: string, amount: number, finalCapture: boolean, invoiceId: string) {
  if (!paypalConfigured()) return { mode: 'SIMULATED' as const, captureId: sim('CAPTURE'), status: 'COMPLETED' };
  const { payments } = sdk();
  try {
    const r = await payments.captureAuthorizedPayment({ authorizationId, prefer: 'return=representation', paypalRequestId: invoiceId, body: { amount: money(amount), finalCapture, invoiceId } });
    return { mode: paypalMode(), captureId: r.result.id!, status: String(r.result.status) };
  } catch (e) { throw new Error(errMsg(e)); }
}

export async function voidAuthorization(authorizationId: string) {
  if (!paypalConfigured()) return { mode: 'SIMULATED' as const, status: 'VOIDED' };
  const { payments } = sdk();
  try { await payments.voidPayment({ authorizationId }); return { mode: paypalMode(), status: 'VOIDED' }; } catch (e) { throw new Error(errMsg(e)); }
}

export async function refundCapture(captureId: string, amount: number) {
  if (!paypalConfigured()) return { mode: 'SIMULATED' as const, refundId: sim('REFUND'), status: 'COMPLETED' };
  const { payments } = sdk();
  try {
    const r = await payments.refundCapturedPayment({ captureId, body: { amount: money(amount) } });
    return { mode: paypalMode(), refundId: r.result.id!, status: String(r.result.status) };
  } catch (e) { throw new Error(errMsg(e)); }
}

async function token() {
  const r = await fetch(`${base()}/v1/oauth2/token`, {
    method: 'POST',
    headers: { authorization: 'Basic ' + Buffer.from(`${process.env.PAYPAL_CLIENT_ID}:${process.env.PAYPAL_CLIENT_SECRET}`).toString('base64'), 'content-type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=client_credentials',
  });
  if (!r.ok) throw new Error(`PayPal OAuth ${r.status}`);
  return ((await r.json()) as any).access_token as string;
}

/** Payouts API (POST /v1/payments/payouts). Requires Payouts to be enabled on the PayPal account. */
export async function sendPayout(opts: { receiverEmail: string; amount: number; note: string; senderItemId: string; batchId: string }) {
  if (!paypalConfigured()) return { mode: 'SIMULATED' as const, payoutBatchId: sim('PAYOUT'), batchStatus: 'SUCCESS', itemStatus: 'SUCCESS' };
  const r = await fetch(`${base()}/v1/payments/payouts`, {
    method: 'POST',
    headers: { authorization: `Bearer ${await token()}`, 'content-type': 'application/json', 'paypal-request-id': opts.batchId },
    body: JSON.stringify({
      sender_batch_header: { sender_batch_id: opts.batchId, email_subject: 'VeriPay milestone payment', email_message: opts.note.slice(0, 255) },
      items: [{ recipient_type: 'EMAIL', amount: { value: opts.amount.toFixed(2), currency: 'USD' }, receiver: opts.receiverEmail, note: opts.note.slice(0, 4000), sender_item_id: opts.senderItemId }],
    }),
  });
  const j: any = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(`PayPal Payouts ${r.status}: ${j.name || ''} ${j.message || ''}`.trim());
  return { mode: paypalMode(), payoutBatchId: j.batch_header.payout_batch_id as string, batchStatus: j.batch_header.batch_status as string, itemStatus: 'PENDING' };
}

export async function getPayoutStatus(batchId: string) {
  if (!paypalConfigured() || batchId.startsWith('SIM-')) return { batchStatus: 'SUCCESS', itemStatus: 'SUCCESS' };
  const r = await fetch(`${base()}/v1/payments/payouts/${encodeURIComponent(batchId)}`, { headers: { authorization: `Bearer ${await token()}` } });
  const j: any = await r.json();
  return { batchStatus: j.batch_header?.batch_status as string, itemStatus: j.items?.[0]?.transaction_status as string };
}

/** POST /v1/notifications/verify-webhook-signature — webhooks are only trusted when PayPal confirms SUCCESS. */
export async function verifyWebhook(headers: Record<string, any>, event: any) {
  if (!paypalConfigured() || !process.env.PAYPAL_WEBHOOK_ID) return false;
  const r = await fetch(`${base()}/v1/notifications/verify-webhook-signature`, {
    method: 'POST',
    headers: { authorization: `Bearer ${await token()}`, 'content-type': 'application/json' },
    body: JSON.stringify({
      auth_algo: headers['paypal-auth-algo'], cert_url: headers['paypal-cert-url'], transmission_id: headers['paypal-transmission-id'],
      transmission_sig: headers['paypal-transmission-sig'], transmission_time: headers['paypal-transmission-time'], webhook_id: process.env.PAYPAL_WEBHOOK_ID, webhook_event: event,
    }),
  });
  const j: any = await r.json().catch(() => ({}));
  return j.verification_status === 'SUCCESS';
}
